#!/usr/bin/env node
// Turns tee.png (a linen T-shirt) into 4 product photos with Modelfy and prints the photo links.
//
// Usage:  MODELFY_API_KEY=mfy_... node make-photos.mjs [path/to/product.png]
//         (or: node --env-file=.env make-photos.mjs)
// Default image: tee.png in the same folder as this script.

import { readFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const MCP_URL = "https://classification-celebs-apparently-rather.trycloudflare.com/mcp";
const PHOTO_COUNT = 4;
const ASPECT_RATIO = "4:5";
const TIMEOUT_MS = 15 * 60 * 1000; // give up waiting for the session after 15 minutes

const apiKey = process.env.MODELFY_API_KEY;
if (!apiKey) {
  console.error("MODELFY_API_KEY is not set. Put it in .env or export it, then run again.");
  process.exit(1);
}

const here = path.dirname(fileURLToPath(import.meta.url));
const imagePath = process.argv[2] ?? path.join(here, "tee.png");

// ---- MCP over Streamable HTTP (JSON-RPC) -----------------------------------

let sessionId = null;
let nextId = 1;

function parseBody(text, contentType, id) {
  if (contentType.includes("text/event-stream")) {
    // SSE: pick the JSON-RPC message that answers our request id.
    for (const line of text.split("\n")) {
      if (!line.startsWith("data:")) continue;
      const msg = JSON.parse(line.slice(5).trim());
      if (msg.id === id) return msg;
    }
    throw new Error("No matching response in event stream");
  }
  return JSON.parse(text);
}

async function rpc(method, params) {
  const id = nextId++;
  const res = await fetch(MCP_URL, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Accept: "application/json, text/event-stream",
      Authorization: `Bearer ${apiKey}`,
      ...(sessionId ? { "Mcp-Session-Id": sessionId } : {}),
    },
    body: JSON.stringify({ jsonrpc: "2.0", id, method, params }),
  });
  const sid = res.headers.get("mcp-session-id");
  if (sid) sessionId = sid;
  const text = await res.text();
  if (!res.ok) throw new Error(`MCP ${method} failed: HTTP ${res.status} ${text.slice(0, 300)}`);
  const msg = parseBody(text, res.headers.get("content-type") ?? "", id);
  if (msg.error) throw new Error(`MCP ${method} error: ${msg.error.message}`);
  return msg.result;
}

async function notify(method) {
  await fetch(MCP_URL, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Accept: "application/json, text/event-stream",
      Authorization: `Bearer ${apiKey}`,
      ...(sessionId ? { "Mcp-Session-Id": sessionId } : {}),
    },
    body: JSON.stringify({ jsonrpc: "2.0", method }),
  });
}

// Calls a Modelfy tool and returns its structured result. Throws on tool errors.
async function callTool(name, args = {}) {
  const result = await rpc("tools/call", { name, arguments: args });
  if (result.isError) {
    const text = result.content?.map((c) => c.text).join(" ") ?? "unknown error";
    throw new Error(`${name} failed: ${text}`);
  }
  if (result.structuredContent) return result.structuredContent;
  return JSON.parse(result.content.at(-1).text);
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ---- The workflow ----------------------------------------------------------

async function main() {
  await rpc("initialize", {
    protocolVersion: "2025-06-18",
    capabilities: {},
    clientInfo: { name: "make-photos", version: "1.0.0" },
  });
  await notify("notifications/initialized");

  const account = await callTool("get_account");
  console.log(`Account: ${account.keyKind} key, ${account.credits} credits${account.sandbox ? " (sandbox: photos are samples, nothing is spent)" : ""}`);

  // 1. Upload the product photo from code (presigned PUT, bytes never go through the model).
  const bytes = await readFile(imagePath);
  const contentType = imagePath.toLowerCase().endsWith(".png") ? "image/png" : "image/jpeg";
  const session = await callTool("create_upload_session", {
    files: [{ content_type: contentType, bytes: bytes.length }],
  });
  const upload = session.uploads[0];
  const put = await fetch(upload.put_url, { method: "PUT", headers: upload.headers, body: bytes });
  if (!put.ok) throw new Error(`Upload failed: HTTP ${put.status}`);

  // 2. Wait until Modelfy has accepted the file.
  let uploaded;
  for (let i = 0; i < 30; i++) {
    uploaded = await callTool("get_uploaded_photos", { session_id: session.session_id });
    if (uploaded.rejected.length) {
      throw new Error(`Modelfy rejected the photo: ${uploaded.rejected[0].reason}`);
    }
    if (uploaded.pending === 0 && uploaded.ready_upload_ids.length) break;
    await sleep(2000);
  }
  if (!uploaded?.ready_upload_ids.length) throw new Error("The uploaded photo never became ready");

  // 3. Check the options this account accepts (aspect ratio, photos per product).
  const options = await callTool("get_photo_options");
  if (!options.aspectRatios.includes(ASPECT_RATIO)) {
    throw new Error(`Aspect ratio ${ASPECT_RATIO} not offered; options: ${options.aspectRatios.join(", ")}`);
  }
  if (PHOTO_COUNT < options.photosPerProduct.min || PHOTO_COUNT > options.photosPerProduct.max) {
    throw new Error(`Photos per product must be ${options.photosPerProduct.min}-${options.photosPerProduct.max}`);
  }

  // 4. Plan the session: product only, plain light grey studio background, nothing spent yet.
  const plan = await callTool("plan_photos", {
    products: [{ upload_ids: [uploaded.ready_upload_ids[0]], name: "Linen T-shirt" }],
    mode: "studio",
    background_color: "light grey",
    model_ids: [],
    aspect_ratio: ASPECT_RATIO,
    photos_per_product: PHOTO_COUNT,
    locale: "en",
  });
  console.log(`Plan: ${plan.photos} photos for ${plan.credits} credits (balance ${plan.balance}).`);
  if (!plan.enough_credits) throw new Error("Not enough credits for this session.");

  // 5. Launch. The quote_id makes this safe to retry: it never charges twice.
  const launched = await callTool("generate_photos", { quote_id: plan.quote_id });
  console.log(`Session started: ${launched.name} (${launched.session_id})`);

  // 6. Wait until the session finishes.
  const deadline = Date.now() + TIMEOUT_MS;
  let session2 = launched;
  while (session2.status === "running") {
    if (Date.now() > deadline) throw new Error(`Still running after 15 minutes; check ${launched.web_url}`);
    session2 = await callTool("get_photo_session", { session_id: launched.session_id, wait_seconds: 45 });
    console.log(`  ${session2.status}: ${session2.done}/${session2.total} done, ${session2.failed} failed`);
  }

  // 7. Print the links.
  if (!session2.photos.length) {
    throw new Error(`No photos were made (status: ${session2.status}). Session: ${session2.web_url}`);
  }
  console.log(`\nStatus: ${session2.status}. Photos:`);
  for (const photo of session2.photos) console.log(photo.url);
  console.log(`\nAll photos: ${session2.web_url}`);
}

main().catch((err) => {
  console.error(`Error: ${err.message}`);
  process.exit(1);
});

