#!/usr/bin/env node
// Turns tee.png into 4 product photos with Modelfy and prints the links.
//
// Usage:
//   node --env-file=.env make-photos.mjs [path/to/product.png]
//
// Reads MODELFY_API_KEY from the environment (Node 22 loads .env with --env-file).
// Flow: upload the file -> plan (exact price, nothing spent) -> generate -> wait -> print links.

import { readFile } from "node:fs/promises";
import path from "node:path";

const MCP_URL =
  "https://classification-celebs-apparently-rather.trycloudflare.com/mcp";

// Photo settings. Change here if you want a different look.
const PHOTO_SETTINGS = {
  mode: "studio",            // plain background, product only (no model)
  background_color: "white",
  aspect_ratio: "4:5",
  photos_per_product: 4,
  locale: "en",
};

const API_KEY = process.env.MODELFY_API_KEY;
if (!API_KEY) {
  console.error("MODELFY_API_KEY is not set. Put it in .env or export it.");
  process.exit(1);
}

const inputFile = process.argv[2] ?? path.join(import.meta.dirname, "tee.png");
const CONTENT_TYPES = { ".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".webp": "image/webp" };
const contentType = CONTENT_TYPES[path.extname(inputFile).toLowerCase()];
if (!contentType) {
  console.error(`Unsupported image type: ${inputFile} (use PNG, JPEG, WebP or HEIC)`);
  process.exit(1);
}

// ---- Minimal MCP client over Streamable HTTP ----------------------------------

let sessionId;
let nextId = 1;

function parseBody(text, contentType) {
  if (contentType?.includes("text/event-stream")) {
    const data = text
      .split("\n")
      .filter((line) => line.startsWith("data:"))
      .map((line) => line.slice(5).trim())
      .join("\n");
    return data ? JSON.parse(data) : null;
  }
  return text ? JSON.parse(text) : null;
}

async function post(body) {
  const headers = {
    "content-type": "application/json",
    accept: "application/json, text/event-stream",
    authorization: `Bearer ${API_KEY}`,
  };
  if (sessionId) headers["mcp-session-id"] = sessionId;
  const res = await fetch(MCP_URL, { method: "POST", headers, body: JSON.stringify(body) });
  sessionId ||= res.headers.get("mcp-session-id") ?? undefined;
  const text = await res.text();
  if (!res.ok) throw new Error(`MCP HTTP ${res.status}: ${text.slice(0, 300)}`);
  return parseBody(text, res.headers.get("content-type"));
}

async function connect() {
  await post({
    jsonrpc: "2.0",
    id: nextId++,
    method: "initialize",
    params: { protocolVersion: "2025-06-18", capabilities: {}, clientInfo: { name: "make-photos", version: "1.0.0" } },
  });
  await post({ jsonrpc: "2.0", method: "notifications/initialized" });
}

// Calls a Modelfy tool; throws with the stable error code when the tool fails.
async function callTool(name, args = {}) {
  const reply = await post({
    jsonrpc: "2.0",
    id: nextId++,
    method: "tools/call",
    params: { name, arguments: args },
  });
  if (reply?.error) throw new Error(`${name}: ${reply.error.message}`);
  const result = reply?.result ?? {};
  if (result.isError) {
    const text = result.content?.map((c) => c.text).join(" ") ?? "";
    let code = "";
    let nextStep = "";
    try {
      const err = JSON.parse(text.slice(text.indexOf("{"))).error;
      code = err.code;
      nextStep = err.next_step;
    } catch {
      code = "";
    }
    throw new Error(`${name} failed${code ? ` (${code})` : ""}: ${text}${nextStep ? `\nNext step: ${nextStep}` : ""}`);
  }
  return result.structuredContent ?? JSON.parse(result.content?.[0]?.text ?? "null");
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// ---- Steps --------------------------------------------------------------------

async function uploadProductPhoto(file) {
  const bytes = await readFile(file);
  const session = await callTool("create_upload_session", {
    files: [{ content_type: contentType, bytes: bytes.length }],
  });
  const upload = session.uploads[0];
  const put = await fetch(upload.put_url, { method: "PUT", headers: upload.headers, body: bytes });
  if (!put.ok) throw new Error(`Upload failed: HTTP ${put.status}`);

  for (let i = 0; i < 30; i++) {
    const status = await callTool("get_uploaded_photos", { session_id: session.session_id });
    if (status.rejected?.length) {
      throw new Error(`Photo rejected: ${status.rejected[0].reason}`);
    }
    if (status.ready_upload_ids?.length) return status.ready_upload_ids[0];
    await sleep(2000);
  }
  throw new Error("Timed out waiting for the uploaded photo to be processed");
}

// Returns the photo links from a finished session, whatever the field names are.
function photoLinks(session) {
  const list = session.photos ?? [];
  return list.map((p) => p.url ?? p.link ?? p.full_url).filter(Boolean);
}

// ---- Main ---------------------------------------------------------------------

await connect();

const account = await callTool("get_account");
console.log(`Account: ${account.keyKind} key, ${account.credits} credits${account.sandbox ? " (sandbox: nothing is spent, photos are samples)" : ""}`);

console.log(`Uploading ${path.basename(inputFile)}...`);
const uploadId = await uploadProductPhoto(inputFile);

const quote = await callTool("plan_photos", {
  products: [{ upload_ids: [uploadId], name: "Linen T-shirt" }],
  ...PHOTO_SETTINGS,
});
