input.content:
// make-photos.mjs — turn tee.png into 4 product photos with Modelfy.
//
// Usage:  node --env-file=.env make-photos.mjs
// Needs:  MODELFY_API_KEY in the environment (Node 20.6+ loads it from .env with --env-file).
//
// Flow (Modelfy MCP over Streamable HTTP):
//   create_upload_session -> PUT the file -> get_uploaded_photos
//   list_models / list_backgrounds -> plan_photos (exact price + quote_id)
//   generate_photos -> get_photo_session (wait) -> print the links

import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const MCP_URL = "https://classification-celebs-apparently-rather.trycloudflare.com/mcp";
const HERE = dirname(fileURLToPath(import.meta.url));
const IMAGE_PATH = join(HERE, "tee.png");
const PRODUCT_NAME = "Linen T-shirt";
const PHOTO_COUNT = 4;
const ASPECT_RATIO = "4:5";
const PLACE_DESCRIPTION = "a sunny café terrace in the morning"; // used only if no background is listed
const LOCALE = "en";

const API_KEY = process.env.MODELFY_API_KEY;
if (!API_KEY) {
  console.error("MODELFY_API_KEY is not set. Run: node --env-file=.env make-photos.mjs");
  process.exit(1);
}

// ---- minimal MCP client (JSON-RPC over Streamable HTTP) -------------------

let nextId = 1;
let sessionId = null;

async function rpc(method, params, { notification = false } = {}) {
  const headers = {
    "Content-Type": "application/json",
    Accept: "application/json, text/event-stream",
    Authorization: `Bearer ${API_KEY}`,
    "MCP-Protocol-Version": "2025-06-18",
  };
  if (sessionId) headers["Mcp-Session-Id"] = sessionId;
  const body = { jsonrpc: "2.0", method, params };
  if (!notification) body.id = nextId++;

  const res = await fetch(MCP_URL, { method: "POST", headers, body: JSON.stringify(body) });
  const sid = res.headers.get("mcp-session-id");
  if (sid) sessionId = sid;
  const text = await res.text();
  if (!res.ok) throw new Error(`Modelfy HTTP ${res.status}: ${text.slice(0, 300)}`);
  if (notification) return null;

  // The server answers with SSE ("data: {...}") or plain JSON.
  const dataLine = text.match(/^data: (.*)$/m);
  const msg = JSON.parse(dataLine ? dataLine[1] : text);
  if (msg.error) throw new Error(`MCP error ${msg.error.code}: ${msg.error.message}`);
  return msg.result;
}

async function callTool(name, args = {}) {
  const result = await rpc("tools/call", { name, arguments: args });
  const data = result.structuredContent ?? JSON.parse(result.content.find((c) => c.type === "text" && c.text.startsWith("{"))?.text ?? "{}");
  if (result.isError) {
    const err = data.error ?? {};
    const e = new Error(`${name} failed [${err.code ?? "ERROR"}]: ${err.message ?? result.content?.[0]?.text}${err.next_step ? ` Next: ${err.next_step}` : ""}`);
    e.code = err.code;
    throw e;
  }
  return data;
}

async function init() {
  await rpc("initialize", {
    protocolVersion: "2025-06-18",
    capabilities: {},
    clientInfo: { name: "make-photos", version: "1.0.0" },
  });
  await rpc("notifications/initialized", {}, { notification: true });
}

// ---- steps -----------------------------------------------------------------

async function uploadImage() {
  const bytes = await readFile(IMAGE_PATH);
  const contentType = "image/png";
  const session = await callTool("create_upload_session", {
    files: [{ content_type: contentType, bytes: bytes.length }],
  });
  const file = session.files[0];
  const put = await fetch(file.put_url, {
    method: "PUT",
    headers: file.headers,
    body: bytes,
  });
  if (!put.ok) throw new Error(`Upload PUT failed: HTTP ${put.status} ${await put.text()}`);

  // Wait until Modelfy has accepted the file.
  for (let i = 0; i < 30; i++) {
    const r = await callTool("get_uploaded_photos", { session_id: session.session_id });
    if (r.rejected?.length) throw new Error(`Photo rejected: ${JSON.stringify(r.rejected)}`);
    if (r.photos?.length && !r.pending) return r.photos.map((p) => p.upload_id);
    if (r.uploads?.length && !r.pending) return r.uploads.map((p) => p.upload_id);
    if (!r.pending) break;
    await new Promise((res) => setTimeout(res, 2000));
  }
  throw new Error("Timed out waiting for the uploaded photo to be accepted");
}

async function pickChoices() {
  const models = (await callTool("list_models")).models.filter((m) => m.ready);
  const backgrounds = (await callTool("list_backgrounds")).backgrounds.filter((b) => b.ready);
  if (!models.length) throw new Error("No ready models on this account");
  return { model: models[0], background: backgrounds[0] ?? null };
}

async function main() {
  await init();

  console.log(`Uploading ${IMAGE_PATH} ...`);
  const uploadIds = await uploadImage();
  console.log(`  upload_ids: ${uploadIds.join(", ")}`);

  const { model, background } = await pickChoices();
  console.log(`Model: ${model.name} (${model.id})`);
  console.log(`Place: ${background ? `${background.name} (${background.id})` : PLACE_DESCRIPTION}`);

  const plan = await callTool("plan_photos", {
    products: [{ upload_ids: uploadIds, name: PRODUCT_NAME }],
    mode: "place",
    model_ids: [model.id],
    ...(background ? { background_id: background.id } : { place_description: PLACE_DESCRIPTION }),
    aspect_ratio: ASPECT_RATIO,
    photos_per_product: PHOTO_COUNT,
    locale: LOCALE,
  });
  console.log(`Plan: ${plan.photos} photos for ${plan.credits} credits (balance ${plan.balance}).`);
  if (plan.enough_credits === false) throw new Error("Not enough credits for this session");

  // The API key is the consent: the script was started on purpose to make these photos.
  const launch = await callTool("generate_photos", { quote_id: plan.quote_id, user_confirmed: true });
  const sid = launch.session_id;
  console.log(`Launched session ${sid}. Waiting for photos ...`);

  let session;
  for (;;) {
    session = await callTool("get_photo_session", { session_id: sid, wait_seconds: 45 });
    if (session.status !== "running") break;
  }

  console.log(`\nStatus: ${session.status}`);
  const photos = session.photos ?? [];
  for (const p of photos) {
    console.log(`${p.url ?? "(no link)"}${p.status && p.status !== "completed" ? `  [${p.status}]` : ""}`);
  }
  if (session.web_url) console.log(`All photos: ${session.web_url}`);
  if (!["completed", "partial"].includes(session.status)) process.exitCode = 1;
}

main().catch((err) => {
  console.error(`Error: ${err.message}`);
  process.exit(1);
});

