input.content:
// Turns tee.png (a product photo) into 4 product photos with Modelfy and prints the links.
//
// Usage:  node --env-file=.env make-photos.mjs
//   (needs MODELFY_API_KEY in the environment; the key is a Bearer token for the Modelfy MCP server)

import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const MCP_URL = "https://classification-celebs-apparently-rather.trycloudflare.com/mcp";
const PRODUCT_IMAGE = path.join(path.dirname(fileURLToPath(import.meta.url)), "tee.png");
const PHOTO_COUNT = 4;
const ASPECT_RATIO = "4:5";
const PRODUCT_NAME = "Linen T-shirt";
const CONTENT_TYPE = "image/png";

const apiKey = process.env.MODELFY_API_KEY;
if (!apiKey) {
  console.error("MODELFY_API_KEY is not set. Put it in .env and run: node --env-file=.env make-photos.mjs");
  process.exit(1);
}

// ---- Minimal MCP client over Streamable HTTP ---------------------------------

let sessionId = null;
let nextId = 1;

async function rpc(method, params) {
  const res = await fetch(MCP_URL, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      accept: "application/json, text/event-stream",
      authorization: `Bearer ${apiKey}`,
      "mcp-protocol-version": "2025-06-18",
      ...(sessionId ? { "mcp-session-id": sessionId } : {}),
    },
    body: JSON.stringify({ jsonrpc: "2.0", id: nextId, method, params }),
  });
  const sid = res.headers.get("mcp-session-id");
  if (sid) sessionId = sid;
  const text = await res.text();
  if (!res.ok) throw new Error(`Modelfy HTTP ${res.status}: ${text.slice(0, 300)}`);

  let message;
  if ((res.headers.get("content-type") || "").includes("text/event-stream")) {
    message = text
      .split("\n")
      .filter((line) => line.startsWith("data:"))
      .map((line) => JSON.parse(line.slice(5)))
      .find((m) => m.id === nextId);
  } else {
    message = JSON.parse(text);
  }
  nextId++;
  if (!message) throw new Error(`No response for ${method}`);
  if (message.error) throw new Error(`${method} failed: ${message.error.message}`);
  return message.result;
}

async function notify(method) {
  await fetch(MCP_URL, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${apiKey}`,
      "mcp-protocol-version": "2025-06-18",
      ...(sessionId ? { "mcp-session-id": sessionId } : {}),
    },
    body: JSON.stringify({ jsonrpc: "2.0", method }),
  });
}

// Calls a Modelfy tool and returns its data. Errors come back as isError with
// JSON { error: { code, message, next_step } } in the text.
async function callTool(name, args = {}) {
  const result = await rpc("tools/call", { name, arguments: args });
  const text = result.content?.find((c) => c.type === "text")?.text ?? "";
  let data;
  try {
    data = result.structuredContent ?? JSON.parse(text);
  } catch {
    data = { text };
  }
  if (result.isError) {
    const err = data?.error ?? {};
    throw new Error(`${name}: ${err.code ?? "ERROR"}: ${err.message ?? text}${err.next_step ? ` (${err.next_step})` : ""}`);
  }
  return data;
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// ---- The job -------------------------------------------------------------------

await rpc("initialize", {
  protocolVersion: "2025-06-18",
  capabilities: {},
  clientInfo: { name: "make-photos", version: "1.0.0" },
});
await notify("notifications/initialized");

// 1. Upload the product photo from code (presigned PUT; bytes never go through the model).
const image = await fs.readFile(PRODUCT_IMAGE);
const upload = await callTool("create_upload_session", {
  files: [{ content_type: CONTENT_TYPE, bytes: image.length }],
});
const file = upload.files?.[0];
if (!file?.put_url) throw new Error(`Unexpected upload response: ${JSON.stringify(upload).slice(0, 300)}`);
const putRes = await fetch(file.put_url, {
  method: "PUT",
  headers: file.headers ?? { "Content-Type": CONTENT_TYPE },
  body: image,
});
if (!putRes.ok) throw new Error(`Upload failed: HTTP ${putRes.status} ${await putRes.text()}`);

// Wait until Modelfy has accepted the file.
let uploaded;
for (let attempt = 0; attempt < 30; attempt++) {
  uploaded = await callTool("get_uploaded_photos", { session_id: upload.session_id });
  if (uploaded.rejected?.length) {
    throw new Error(`Modelfy rejected the photo: ${JSON.stringify(uploaded.rejected)}`);
  }
  if (uploaded.photos?.length || uploaded.ready?.length) break;
  await sleep(2000);
}
const uploadId = (uploaded.ready ?? uploaded.photos ?? [])[0]?.upload_id ?? (uploaded.ready ?? uploaded.photos ?? [])[0];
if (!uploadId) throw new Error(`Photo never became ready: ${JSON.stringify(uploaded).slice(0, 300)}`);
console.log(`Uploaded ${PRODUCT_IMAGE} (upload ${uploadId})`);

// 2. Pick a ready model and a ready place from the catalog.
const { models = [] } = await callTool("list_models");
const { backgrounds = [] } = await callTool("list_backgrounds");
const model = models.find((m) => m.ready);
const place = backgrounds.find((b) => b.ready);
if (!model) throw new Error("No ready model available");
if (!place) throw new Error("No ready background available");

// 3. Plan: nothing is spent yet. Print the exact price.
const quote = await callTool("plan_photos", {
  products: [{ upload_ids: [uploadId], name: PRODUCT_NAME }],
  mode: "place",
  model_ids: [model.id],
  background_id: place.id,
  aspect_ratio: ASPECT_RATIO,
  photos_per_product: PHOTO_COUNT,
  direction: "natural light, relaxed",
  locale: "en",
});
if (quote.enough_credits === false) {
  throw new Error(`Not enough credits for this session (${quote.credits} needed, ${quote.balance} available)`);
}
console.log(`Plan: ${PHOTO_COUNT} photos on ${model.name} at ${place.name}, ${quote.credits} credits`);

// 4. Launch. For a live key the key's budget is the consent; a test/sandbox key spends nothing.
const session = await callTool("generate_photos", { quote_id: quote.quote_id });
const sessionIdOut = session.session_id ?? session.id;
console.log(`Session ${sessionIdOut} started`);

// 5. Wait until finished.
let status;
do {
  status = await callTool("get_photo_session", { session_id: sessionIdOut, wait_seconds: 45 });
  console.log(`  status: ${status.status}`);
} while (status.status === "running");

// 6. Print the links.
const photos = (status.photos ?? []).filter((p) => p.url);
if (!photos.length) {
  throw new Error(`No photos were made (status: ${status.status})`);
}
console.log(`\n${photos.length} photo(s), status ${status.status}:`);
for (const p of photos) console.log(p.url);
if (status.web_url) console.log(`\nAll photos: ${status.web_url}`);

