// make-photos.mjs: turns tee.png (a linen T-shirt) into 4 product photos with Modelfy
// and prints the links to the finished photos.
//
// Usage (Node 20.6+):
//   node --env-file=.env make-photos.mjs [path/to/photo.png]
// The API key is read from the MODELFY_API_KEY environment variable.

import { readFile } from "node:fs/promises";
import { basename, extname } from "node:path";

const MCP_URL = "https://classification-celebs-apparently-rather.trycloudflare.com/mcp";
const PHOTO_PATH = process.argv[2] ?? new URL("./tee.png", import.meta.url).pathname;
const PHOTOS = 4;
const ASPECT_RATIO = "4:5";
const CONTENT_TYPES = { ".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".webp": "image/webp", ".heic": "image/heic" };

const apiKey = process.env.MODELFY_API_KEY;
if (!apiKey) {
  console.error("MODELFY_API_KEY is not set. Put it in .env and run: node --env-file=.env make-photos.mjs");
  process.exit(1);
}

// ---- minimal MCP client over Streamable HTTP -------------------------------

let sessionId;
let rpcId = 0;

async function post(body) {
  const res = await fetch(MCP_URL, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      accept: "application/json, text/event-stream",
      authorization: `Bearer ${apiKey}`,
      ...(sessionId ? { "mcp-session-id": sessionId } : {}),
    },
    body: JSON.stringify(body),
  });
  sessionId = res.headers.get("mcp-session-id") ?? sessionId;
  if (!res.ok) throw new Error(`MCP HTTP ${res.status}: ${await res.text()}`);
  const text = await res.text();
  if (!text) return undefined;
  if (text.trimStart().startsWith("{")) return JSON.parse(text);
  // text/event-stream: take the last JSON message that carries a response
  const messages = [...text.matchAll(/^data: (.*)$/gm)].map((m) => JSON.parse(m[1]));
  return messages.findLast((m) => m.id !== undefined) ?? messages.at(-1);
}

async function connect() {
  const init = await post({
    jsonrpc: "2.0",
    id: ++rpcId,
    method: "initialize",
    params: { protocolVersion: "2025-06-18", capabilities: {}, clientInfo: { name: "make-photos", version: "1.0.0" } },
  });
  if (init.error) throw new Error(`initialize failed: ${init.error.message}`);
  await post({ jsonrpc: "2.0", method: "notifications/initialized" });
}

// Calls a tool and returns its structuredContent. Throws with Modelfy's error code on failure.
async function tool(name, args = {}) {
  const res = await post({ jsonrpc: "2.0", id: ++rpcId, method: "tools/call", params: { name, arguments: args } });
  if (res.error) throw new Error(`${name}: ${res.error.message}`);
  const result = res.result;
  if (result.isError) {
    const err = JSON.parse(result.content.at(-1).text).error;
    throw new Error(`${name} failed [${err.code}]: ${err.message} ${err.next_step ?? ""}`.trim());
  }
  return result.structuredContent;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ---- the pipeline ----------------------------------------------------------

await connect();

// 1. Upload the product photo (bytes go straight to the presigned URL, not through this script's MCP calls).
const bytes = await readFile(PHOTO_PATH);
const contentType = CONTENT_TYPES[extname(PHOTO_PATH).toLowerCase()];
if (!contentType) throw new Error(`Unsupported image type: ${PHOTO_PATH}`);

const session = await tool("create_upload_session", { files: [{ content_type: contentType, bytes: bytes.length }] });
const upload = session.uploads[0];
const put = await fetch(upload.put_url, { method: "PUT", headers: upload.headers, body: bytes });
if (!put.ok) throw new Error(`Upload of ${basename(PHOTO_PATH)} failed: HTTP ${put.status}`);

// Wait until Modelfy has accepted the file.
let uploadId;
for (let i = 0; i < 20 && !uploadId; i++) {
  const got = await tool("get_uploaded_photos", { session_id: session.session_id });
  if (got.rejected?.length) throw new Error(`Photo rejected: ${JSON.stringify(got.rejected)}`);
  uploadId = got.ready?.[0]?.upload_id;
  if (!uploadId) await sleep(1000);
}
if (!uploadId) throw new Error("Modelfy did not accept the photo in time");
console.error(`Product photo accepted (${basename(PHOTO_PATH)})`);

// 2. Plan the session: 4 photos of the product alone on a plain light-grey studio background.
const plan = await tool("plan_photos", {
  products: [{ upload_ids: [uploadId], name: "Linen T-shirt" }],
  mode: "studio",
  background_color: "light grey",
  model_ids: [],
  aspect_ratio: ASPECT_RATIO,
  photos_per_product: PHOTOS,
  direction: "clean e-commerce product photos, soft even light, fabric texture visible",
  locale: "en",
});
if (!plan.enough_credits) throw new Error(`Not enough credits: plan costs ${plan.credits}, balance ${plan.balance}`);
console.error(`Planned ${PHOTOS} photos for ${plan.credits} credits`);

// 3. Launch the planned session.
const launch = await tool("generate_photos", { quote_id: plan.quote_id });
const sessionIdPhotos = launch.session_id;

// 4. Wait until the session finishes.
let photoSession;
do {
  photoSession = await tool("get_photo_session", { session_id: sessionIdPhotos, wait_seconds: 45 });
  if (photoSession.status === "running") console.error("Still making photos...");
} while (photoSession.status === "running");

// 5. Print the links.
console.error(`Session ${photoSession.status}`);
const links = (photoSession.photos ?? []).filter((p) => p.url).map((p) => p.url);
if (!links.length) throw new Error(`No photos were made (status: ${photoSession.status})`);
for (const url of links) console.log(url);
if (photoSession.web_url) console.error(`All photos: ${photoSession.web_url}`);

