import json, os, sys, time, urllib.request, urllib.error

BASE = "https://classification-celebs-apparently-rather.trycloudflare.com"
ENV_PATH = "/work/.env"
data = json.load(open("/tmp/modelfy_device.json"))
device_code = data["device_code"]
interval = data.get("interval", 5)
deadline = time.time() + data.get("expires_in", 600) + 5


def post(path, body):
    req = urllib.request.Request(
        BASE + path,
        data=json.dumps(body).encode(),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, json.loads(r.read() or b"{}")
    except urllib.error.HTTPError as e:
        try:
            return e.code, json.loads(e.read() or b"{}")
        except Exception:
            return e.code, {}


while time.time() < deadline:
    status, body = post("/device/token", {"device_code": device_code})
    if status == 200 and "api_key" in body:
        key = body["api_key"]
        with open(ENV_PATH, "w") as f:
            f.write(f"MODELFY_API_KEY={key}\n")
        os.chmod(ENV_PATH, 0o600)
        print("APPROVED kind=%s budget=%s" % (body.get("kind"), json.dumps(body.get("budget"))))
        print("Saved key to", ENV_PATH, "(key not printed)")
        sys.exit(0)
    err = body.get("error")
    if err == "authorization_pending":
        pass
    elif err == "slow_down":
        interval += 5
    elif err in ("access_denied", "expired_token"):
        print("STOPPED:", err)
        sys.exit(2)
    else:
        print("UNEXPECTED", status, json.dumps(body))
    time.sleep(interval)

print("STOPPED: timed out waiting for approval")
sys.exit(3)

