import json, os, sys, time, urllib.request, urllib.error

BASE = "https://classification-celebs-apparently-rather.trycloudflare.com"
ENV_PATH = "/work/.env"
data = json.load(open("/tmp/dev2.json"))
device_code = data["device_code"]
interval = data.get("interval", 5)
deadline = time.time() + data.get("expires_in", 600) + 5


def post(url, body, headers=None):
    h = {"Content-Type": "application/json"}
    h.update(headers or {})
    req = urllib.request.Request(url, data=json.dumps(body).encode(), headers=h, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, r.read().decode()
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode()


def account_info(key):
    status, text = post(
        BASE + "/mcp",
        {"jsonrpc": "2.0", "id": 1, "method": "tools/call",
         "params": {"name": "get_account", "arguments": {}}},
        {"Authorization": "Bearer " + key, "Accept": "application/json, text/event-stream"},
    )
    for line in text.splitlines():
        if line.startswith("data: "):
            msg = json.loads(line[6:])
            return msg.get("result", {}).get("structuredContent", {})
    return {}


while time.time() < deadline:
    status, text = post(BASE + "/device/token", {"device_code": device_code})
    try:
        body = json.loads(text or "{}")
    except Exception:
        body = {}
    if status == 200 and "api_key" in body:
        key = body["api_key"]
        info = account_info(key)
        print("GOT KEY keyKind=%s sandbox=%s plan=%s credits=%s" % (
            info.get("keyKind"), info.get("sandbox"), info.get("plan"), info.get("credits")))
        if info.get("sandbox") or info.get("keyKind") not in ("live", "test"):
            print("REJECTED: key is not tied to an account; not saved")
            sys.exit(4)
        with open(ENV_PATH, "w") as f:
            f.write(f"MODELFY_API_KEY={key}\n")
        os.chmod(ENV_PATH, 0o600)
        print("SAVED to", ENV_PATH, "(key not printed)")
        sys.exit(0)
    err = body.get("error")
    if err == "authorization_pending":
        pass
    elif err == "slow_down":
        interval += 5
    elif err in ("access_denied", "expired_token"):
        print("STOPPED:", err)
        sys.exit(2)
    else:
        print("UNEXPECTED", status, text[:200])
    time.sleep(interval)

print("STOPPED: timed out")
sys.exit(3)

