import json, os, sys, time, urllib.request, urllib.error

BASE = "https://classification-celebs-apparently-rather.trycloudflare.com"
DEVICE_CODE = json.load(open("/tmp/modelfy-device.json"))["device_code"]
ENV_PATH = "/work/.env"
STATUS = "/tmp/modelfy-poll/status.txt"

def status(msg):
    with open(STATUS, "a") as f:
        f.write(msg + "\n")

def post(path, body):
    req = urllib.request.Request(BASE + path, data=json.dumps(body).encode(),
                                 headers={"Content-Type": "application/json"}, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, json.loads(r.read() or b"{}")
    except urllib.error.HTTPError as e:
        try:
            return e.code, json.loads(e.read() or b"{}")
        except Exception:
            return e.code, {}

interval = 5
deadline = time.time() + 590
while time.time() < deadline:
    code, data = post("/device/token", {"device_code": DEVICE_CODE})
    if code == 200 and "api_key" in data:
        key = data["api_key"]
        fd = os.open(ENV_PATH, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        with os.fdopen(fd, "w") as f:
            f.write(f"MODELFY_API_KEY={key}\n")
        status(f"APPROVED kind={data.get('kind')} budget={json.dumps(data.get('budget'))}")
        sys.exit(0)
    err = data.get("error")
    if err == "authorization_pending":
        pass
    elif err == "slow_down":
        interval += 5
    else:
        status(f"STOPPED http={code} error={err}")
        sys.exit(1)
    time.sleep(interval)

status("EXPIRED no approval within 10 minutes")
sys.exit(2)

